166	    default String formatFiscalYear(Owner owner) {
167	        if (owner == null || owner.getRegistrationDate() == null) {
168	            return null;
169	        }
170	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
171	    }
172	
173	    /**
174	     * Returns the calendar year in which the fiscal year containing {@code date} begins. The
175	     * fiscal year starts on 1 July, so dates in July through December belong to the fiscal year
176	     * starting in their own calendar year, while dates in January through June belong to the
177	     * fiscal year that started in the previous calendar year.
178	     */
179	    private static int fiscalYearStart(LocalDate date) {
180	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
181	    }
182	
183	    /**
184	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
185	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
186	     * code. Returns {@code null} when the customer code is absent.
187	     *
188	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
189	     * applied only where referenced via {@code qualifiedByName}.
190	     */
191	    @Named("formatCheckDigit")
192	    default Integer formatCheckDigit(Owner owner) {
193	        if (owner == null || owner.getCustomerCode() == null) {
194	            return null;
195	        }
196	        return LuhnCheckDigit.compute(owner.getCustomerCode());
197	    }
198	
199	    /**
200	     * Computes an owner's membership points, as required by the API's read-only
201	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
202	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
203	     * of 3 or more members, plus 3 when the owner's tenure spans at least one elapsed fiscal year
204	     * (the registration date's fiscal year precedes the current fiscal year, the fiscal year
205	     * starting on 1 July).
206	     *
207	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
208	     * applied only where referenced via {@code qualifiedByName}.
209	     */
210	    @Named("formatMembershipPoints")
211	    default Integer formatMembershipPoints(Owner owner) {
212	        if (owner == null) {
213	            return null;
214	        }
215	        int points = 0;
216	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
217	            points += 2;
218	        }
219	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
220	            points += 1;
221	        }
222	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
223	            points += 2;
224	        }
225	        if (owner.getRegistrationDate() != null
226	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
227	            points += 3;
228	        }
229	        return points;
230	    }
231	
232	    /**
233	     * Derives an owner's membership level, as required by the API's read-only
234	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
235	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
236	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
237	     *
238	     * <p>The result is then capped by the owner's {@link Owner#getMembershipLevelCap()
239	     * membershipLevelCap}, when present: a new owner's level cannot exceed one above the highest
240	     * membership level among the household members that already existed when it was created, so the
241	     * returned level is the lower of the derived level and that stored cap. When no cap applies (no
242	     * existing household member on creation) the derived level stands.
243	     *
244	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
245	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
246	     * to record the membership level on the create audit line).
247	     */
248	    @Named("formatMembershipLevel")
249	    default Integer formatMembershipLevel(Owner owner) {
250	        if (owner == null) {
251	            return null;
252	        }
253	        int points = formatMembershipPoints(owner);
254	        int level;
255	        if (points <= 1) {
256	            level = 1;
257	        }
258	        else if (points <= 3) {
259	            level = 2;
260	        }
261	        else if (points <= 5) {
262	            level = 3;
263	        }
264	        else {
265	            level = 4;
266	        }
267	        Integer cap = owner.getMembershipLevelCap();
268	        return (cap != null && cap < level) ? cap : level;
269	    }
270	
271	    /**
272	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
273	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
274	     * locality is read from the same region-and-hash identity that the customer code encodes.
275	     * When no customer code is present (e.g. an owner that predates the code), the region is
276	     * resolved directly from the postcode (falling back to the city-to-region table, else
277	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
278	     *
279	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
280	     * applied only where referenced via {@code qualifiedByName}.
281	     */
282	    @Named("formatLocality")
283	    default String formatLocality(Owner owner) {
284	        if (owner == null) {
285	            return null;
286	        }
287	        String customerCode = owner.getCustomerCode();
288	        if (customerCode != null) {
289	            int dash = customerCode.indexOf('-');
290	            if (dash > 0) {
291	                return customerCode.substring(0, dash);
292	            }
293	        }
294	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
295	    }
296	
297	    /**
298	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
299	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
300	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
301	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
302	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
303	     *
304	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
305	     * applied only where referenced via {@code qualifiedByName}.
306	     */
307	    @Named("formatTimezone")
308	    default String formatTimezone(Owner owner) {
309	        if (owner == null) {
310	            return null;
311	        }
312	        return LocalityResolver.timezone(formatLocality(owner));
313	    }
314	
315	    /**
316	     * Derives an owner's preferred contact channel, as required by the API's read-only
317	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
318	     * otherwise {@code 'PHONE'}.
319	     *
320	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
321	     * applied only where referenced via {@code qualifiedByName}.
322	     */
323	    @Named("formatContactPreference")
324	    default String formatContactPreference(Owner owner) {
325	        if (owner == null) {
326	            return null;
327	        }
328	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
329	    }
330	
331	    /**
332	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
333	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
334	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
335	     * no birth date was supplied (so the field is absent), or when no registration date is yet
336	     * known against which to compute the age.
337	     *
338	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
339	     * applied only where referenced via {@code qualifiedByName}.
340	     */
341	    @Named("formatAgeBand")
342	    default String formatAgeBand(Owner owner) {
343	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
344	            return null;
345	        }
346	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
347	        if (age < 18) {
348	            return "MINOR";
349	        }
350	        if (age < 65) {
351	            return "ADULT";
352	        }
353	        return "SENIOR";
354	    }
355	
356	    private static String initial(String name) {
357	        if (name == null || name.isEmpty()) {
358	            return "";
359	        }
360	        return Character.toUpperCase(name.charAt(0)) + ".";
361	    }
362	
363	    Owner toOwner(OwnerDto ownerDto);
364	
365	    @Mapping(target = "id", ignore = true)
366	    @Mapping(target = "pets", ignore = true)
367	    @Mapping(target = "addressLine1", ignore = true)
368	    @Mapping(target = "addressLine2", ignore = true)
369	    @Mapping(target = "address", ignore = true)
370	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
371	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
372	    @Mapping(target = "title", source = "title", qualifiedByName = "mapTitle")
373	    Owner toOwner(OwnerFieldsDto ownerDto);
374	
375	    /**
376	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
377	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
378	     * title was supplied. This is the single place the inbound title conversion lives: it runs
379	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
380	     * update path, keeping both consistent.
381	     *
382	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
383	     * applied only where referenced via {@code qualifiedByName}.
384	     */
385	    @Named("mapTitle")
386	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
387	        return title == null ? null : title.getValue();
388	    }
389	
390	    /**
391	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
392	     * normalizing each. This is the single place the structured-field normalization rule lives: it
393	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
394	     * called directly on the update path to keep both create and update consistent.
395	     *
396	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
397	     * {@code address} is set to the {@link #composeAddress composed} effective address.
398	     */
399	    @AfterMapping
400	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
401	        if (ownerDto == null) {
402	            return;
403	        }
404	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
405	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
406	        owner.setAddress(composeAddress(ownerDto));
407	    }
408	
409	    /**
410	     * Composes the effective, normalized postal address for an owner from the supplied fields,
411	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
412	     * present, the result is the normalized {@code addressLine1} with the normalized
413	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
414	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
415	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
416	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
417	     */
418	    default String composeAddress(OwnerFieldsDto ownerDto) {
419	        if (ownerDto == null) {
420	            return null;
421	        }
422	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
423	        if (line1 != null && !line1.isEmpty()) {
424	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
425	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
426	        }
427	        return normalizeAddress(ownerDto.getAddress());
428	    }
429	
430	    /**
431	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
432	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
433	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
434	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
435	     * {@code '12 MAIN STREET'}.
436	     *
437	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
438	     * only where referenced via {@code qualifiedByName}.
439	     */
440	    @Named("normalizeAddress")
441	    default String normalizeAddress(String address) {
442	        return AddressNormalizer.normalize(address);
443	    }
444	
445	    /**
446	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
447	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
448	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
449	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
450	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
451	     *
452	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
453	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
454	     *
455	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
456	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
457	     */
458	    @Named("normalizeTelephone")
459	    default String normalizeTelephone(String telephone) {
460	        return TelephoneNormalizer.toE164(telephone);
461	    }
462	
463	    /**
464	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
465	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
466	     * guarantees any value present is a syntactically valid address.
467	     *
468	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
469	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
470	     * e.g. on update).
471	     */
472	    @Named("normalizeEmail")
473	    default String normalizeEmail(String email) {
474	        return email == null ? null : email.toLowerCase(Locale.ROOT);
475	    }
476	
477	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
478	
479	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
480	
481	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
482	        OwnerPageDto ownerPageDto = new OwnerPageDto();
483	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
484	        ownerPageDto.setPage(ownerPage.getNumber());
485	        ownerPageDto.setSize(ownerPage.getSize());
486	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
487	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
488	        return ownerPageDto;
489	    }
490	}
